import data from "./airport-map-data.json";

/**
 * The airport map's geometry and the arrival routes drawn over it.
 * airport-map-data.json is generated by scripts/build-airport-map.mjs from the
 * airport's official floor plans and OpenStreetMap; nothing here adds a place
 * that is not in that file. Routes only connect objects the file contains.
 */
export type Point = [x: number, z: number];
export type MapObject = { kind: string; x: number; z: number; w?: number; d?: number; count?: number; label?: string; key?: string; dir?: number[] };
export type Plate = { kind: string; points: number[][]; holes?: number[][][] };
export type Level = { source: string; plates: Plate[]; objects: MapObject[]; exit?: { x: number; z: number } };

export type TerminalId = "t2" | "t1";
export type ViewId = TerminalId | "overview";
export const airportMap = data as unknown as {
  t2: { levels: Record<"pier" | "extensionPier" | "ground", Level> };
  t1: { levels: Record<"pier" | "ground", Level> };
  overview: {
    terminals: { id: string; points: number[][] }[];
    buildings: number[][][]; parking: number[][][]; aprons: number[][][];
    roads: number[][][]; serviceRoads: number[][][]; runways: number[][][]; taxiways: number[][][];
    stops: { key: string; x: number; z: number }[];
  };
};

export const terminalLevels: Record<TerminalId, readonly string[]> = {
  t2: ["pier", "extensionPier", "ground"],
  t1: ["pier", "ground"],
};

/** One leg of an arrival: the level it is on, and the line walked on that level. */
export type RouteStep = { id: string; level: string; points: Point[] };

const mean = (objects: MapObject[]): Point => [
  objects.reduce((sum, o) => sum + o.x, 0) / objects.length,
  objects.reduce((sum, o) => sum + o.z, 0) / objects.length,
];
const at = (o: { x: number; z: number }): Point => [o.x, o.z];

function find(level: Level, kind: string, match: (o: MapObject) => boolean = () => true): MapObject[] {
  const found = level.objects.filter((o) => o.kind === kind && match(o));
  if (found.length === 0) throw new Error(`airport map: no ${kind} on ${level.source}`);
  return found;
}
const rightmost = (objects: MapObject[]) => objects.reduce((a, b) => (b.x > a.x ? b : a));
const arrows = (level: Level, dx: number, dz: number) => find(level, "arrow", (o) => o.dir?.[0] === dx && o.dir?.[1] === dz);

/** Passport hall of a round pier: arrivals door, booths, then the escalator down to baggage claim. */
function pierStep(level: Level): RouteStep {
  const booths = mean(find(level, "passport"));
  const corridor = mean(arrows(level, 0, 1));
  const down = rightmost(find(level, "escalator"));
  const door = find(level, "sign", (o) => o.key === "arrivalsGateA")[0];
  return { id: "passport", level: "pier", points: [at(door), [door.x + 4, booths[1] - 4], [booths[0], booths[1] - 4], [booths[0], corridor[1]], [down.x - 6, corridor[1]], at(down)] };
}

function t2Route(): RouteStep[] {
  const ground = airportMap.t2.levels.ground;
  const exit = ground.exit!;
  const belt = find(ground, "belt", (o) => o.label === "204")[0];
  const aisle = arrows(ground, 1, 0)[0];
  const customs = find(ground, "customs").reduce((a, b) => (a.z < b.z ? a : b));
  const toLandside = arrows(ground, 0, 1)[0];
  const row = [...find(ground, "police"), ...find(ground, "shelter")];
  const last = row[row.length - 1];
  // Counters A–L back onto the terminal; passengers pass in front, between them and the numbered desks.
  const walkway = (row[0].z + find(ground, "desks")[0].z) / 2;
  return [
    pierStep(airportMap.t2.levels.pier),
    { id: "baggage", level: "ground", points: [at(find(ground, "escalator")[0]), [belt.x - 4, belt.z - belt.d! / 2 - 2], [belt.x - 4, aisle.z], at(aisle)] },
    { id: "customs", level: "ground", points: [at(aisle), [customs.x - 3, aisle.z], [customs.x - 3, customs.z + 3], [toLandside.x, customs.z + 3], at(toLandside)] },
    { id: "exit", level: "ground", points: [at(toLandside), [exit.x, exit.z]] },
    { id: "meetGreet", level: "ground", points: [[exit.x, exit.z], [exit.x, walkway], [last.x, walkway]] },
  ];
}

function t1Route(): RouteStep[] {
  const ground = airportMap.t1.levels.ground;
  const exit = ground.exit!;
  const belt = find(ground, "belt", (o) => o.label === "103")[0];
  const toLandside = arrows(ground, 0, 1).reduce((a, b) => (a.z < b.z ? a : b));
  const screening = mean(find(ground, "security"));
  const down = find(ground, "escalator").reduce((a, b) => (Math.abs(a.x - belt.x) < Math.abs(b.x - belt.x) ? a : b));
  return [
    pierStep(airportMap.t1.levels.pier),
    { id: "baggage", level: "ground", points: [at(down), [belt.x + 5, belt.z - belt.d! / 2 - 2], [belt.x + 5, toLandside.z - 2], [toLandside.x, toLandside.z - 2]] },
    { id: "customs", level: "ground", points: [[toLandside.x, toLandside.z - 2], at(toLandside), [toLandside.x, screening[1]], [screening[0], screening[1] + 4]] },
    { id: "exit", level: "ground", points: [[screening[0], screening[1] + 4], [exit.x, screening[1] + 4], [exit.x, exit.z]] },
  ];
}

export const arrivalRoutes: Record<TerminalId, RouteStep[]> = { t2: t2Route(), t1: t1Route() };
